package com.nexamart.backend.api;import com.nexamart.backend.api.ApiModels.*;import com.nexamart.backend.service.CatalogService;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/catalog")public class CatalogController{final CatalogService s;public CatalogController(CatalogService s){this.s=s;}@GetMapping("/categories")PageResponse<CategoryResponse> categories(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String search,@RequestParam(required=false)Boolean active){return s.categories(page,pageSize,search,active);}@GetMapping("/products")PageResponse<ProductResponse> products(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String search,@RequestParam(required=false)Boolean active,@RequestParam(required=false)Long categoryId){return s.products(page,pageSize,search,active,categoryId);}}
